        board._emittedCardIds.add(card.id);
      }
      board._emittedSummaryTurns.add(card.turn);
    }
    return board;
  }

  ShellJobBoard._() : turn = 1;

  /// All cards ever, in start order (capped at [_maxBoardHistory]).
  final List<TaskBlock> _cards = [];

